async function accederRetiro(cajaId){
 try{
   if(!turno)throw new Error('Primero abre un turno para poder retirar.');
   const acceso=await window.GYD_Acceso.abrir('retiro',cajaId);
   if(acceso)window.location.assign('pos_retiros.php?caja_id='+encodeURIComponent(cajaId));
 }catch(e){notify(e.message,true);}
}
